120	// rejectDuplicateKeys tokenizes the whole JSON document and rejects repeated
121	// member names at any object nesting level or trailing content.
122	func rejectDuplicateKeys(data []byte) error {
123		dec := json.NewDecoder(bytes.NewReader(data))
124		dec.UseNumber()
