134	func scanDuplicateKeys(dec *json.Decoder) error {
135		t, err := dec.Token()
136		if err != nil {
137			return err
138		}
139		d, ok := t.(json.Delim)
140		if !ok {
141			return nil
142		}
143		switch d {
144		case '{':
145			seen := make(map[string]struct{})
146			for dec.More() {
147				keyTok, err := dec.Token()
148				if err != nil {
149					return err
150				}
151				key := keyTok.(string)
152				if _, dup := seen[key]; dup {
153					return errDuplicateKey
154				}
155				seen[key] = struct{}{}
156				if err := scanDuplicateKeys(dec); err != nil {
157					return err
158				}
159			}
160			if _, err := dec.Token(); err != nil {
161				return err
162			}
