243	// simulateSchedule runs an event-driven single-core fixed-priority preemptive
244	// simulation over [0, horizon).
245	func simulateSchedule(tasks []scheduledTask, horizon int64) analyzeResponse {
246		n := len(tasks)
247		remaining := make([]int64, n)
248		for i, t := range tasks {
249			remaining[i] = t.execution
250		}
251		released := make([]bool, n)
252		executed := make([]int64, n)
253		completion := make([]*int64, n)
254	
255		// Indices sorted by (release, input order) for release bookkeeping and
256		// same-priority tie breaking.
257		order := make([]int, n)
258		for i := range order {
259			order[i] = i
260		}
261		sort.Slice(order, func(a, b int) bool {
262			ia, ib := order[a], order[b]
263			if tasks[ia].release != tasks[ib].release {
264				return tasks[ia].release < tasks[ib].release
265			}
266			return ia < ib
267		})
268		nextRelease := 0
269		releaseUpTo := func(now int64) {
270			for nextRelease < n && tasks[order[nextRelease]].release <= now {
271				released[order[nextRelease]] = true
272				nextRelease++
273			}
274		}
275	
276		// Best runnable task: smallest priority, then earliest release, then
277		// earliest input index.
278		bestRunnable := func() int {
279			best := -1
280			for i := 0; i < n; i++ {
281				if !released[i] || remaining[i] <= 0 {
282					continue
283				}
284				if best == -1 {
285					best = i
286					continue
287				}
288				a, b := tasks[i], tasks[best]
289				if a.priority < b.priority ||
290					(a.priority == b.priority && a.release < b.release) ||
291					(a.priority == b.priority && a.release == b.release && i < best) {
292					best = i
293				}
294			}
295			return best
296		}
297	
298		var segments []executionSegment
299		current := -1
300		var now int64
301		for now < horizon {
302			releaseUpTo(now)
303			if current >= 0 && remaining[current] == 0 {
304				current = -1
305			}
306			best := bestRunnable()
307			switch {
308			case current == -1:
309				current = best
310			case best != -1 && tasks[best].priority < tasks[current].priority:
311				// Strictly higher priority preempts; equal priority never does.
312				current = best
313			}
314	
315			if current == -1 {
316				// Idle: jump to the next release (or the horizon).
317				if nextRelease >= n {
318					now = horizon
319					break
320				}
321				now = tasks[order[nextRelease]].release
322				continue
323			}
324	
325			// Run until completion, the horizon, or the next strictly-higher-priority
326			// release, whichever comes first.
327			runEnd := horizon
328			if remaining[current] < horizon-now {
329				runEnd = now + remaining[current]
330			}
331			for k := nextRelease; k < n; k++ {
332				j := order[k]
333				if tasks[j].priority < tasks[current].priority &&
334					tasks[j].release > now && tasks[j].release < runEnd {
335					runEnd = tasks[j].release
336				}
337			}
338	
339			segments = append(segments, executionSegment{index: current, start: now, end: runEnd})
340			delta := runEnd - now
341			executed[current] += delta
342			remaining[current] -= delta
343			now = runEnd
344			if remaining[current] == 0 {
345				done := now
346				completion[current] = &done
347				current = -1
348			}
349		}
350	
351		timeline := make([]timelineInterval, 0, len(segments))
352		for _, seg := range segments {
353			last := len(timeline) - 1
354			if last >= 0 && timeline[last].TaskID == tasks[seg.index].id && timeline[last].End == seg.start {
355				timeline[last].End = seg.end
356				continue
357			}
358			timeline = append(timeline, timelineInterval{
359				TaskID: tasks[seg.index].id,
360				Start:  seg.start,
361				End:    seg.end,
362			})
363		}
364	
365		results := make([]taskResult, n)
366		for i, t := range tasks {
367			var status string
368			switch c := completion[i]; {
369			case c != nil:
370				if *c <= t.deadline {
371					status = "met"
372				} else {
373					status = "missed"
374				}
375			case t.deadline <= horizon:
376				status = "missed"
377			default:
378				status = "pending"
379			}
380			results[i] = taskResult{
381				Executed:       executed[i],
382				Remaining:      remaining[i],
383				Completion:     completion[i],
384				DeadlineStatus: status,
385			}
386		}
387	
388		return analyzeResponse{Timeline: timeline, Results: results}
389	}
