type periodicTaskIn struct {
	ID        string `json:"id"`
	Priority  *int64 `json:"priority"`
	Execution *int64 `json:"execution"`
	Period    *int64 `json:"period"`
	Deadline  *int64 `json:"deadline"`
}

type periodicAnalyzeRequest struct {
	Tasks *[]periodicTaskIn `json:"tasks"`
}

type periodicTaskResult struct {
	ID             string `json:"id"`
	ResponseTime   *int64 `json:"responseTime"`
	DeadlineStatus string `json:"deadlineStatus"`
}

type periodicAnalyzeResponse struct {
	Schedulable bool                  `json:"schedulable"`
	Results     []periodicTaskResult  `json:"results"`
}

type periodicTask struct {
	index     int
	id        string
	priority  int64
	execution int64
	period    int64
	deadline  int64
}

func handlePeriodicAnalyze(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		writeAPIError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	var req periodicAnalyzeRequest
	if !decodeStrictRequest(w, r, &req) {
		return
	}
	tasks, ok := validatePeriodicRequest(&req)
	if !ok {
		writeAPIError(w, http.StatusUnprocessableEntity, "validation_failed")
		return
	}
	resp := analyzePeriodic(tasks)
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(resp)
}

func validatePeriodicRequest(req *periodicAnalyzeRequest) ([]periodicTask, bool) {
	if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
		return nil, false
	}
	tasks := make([]periodicTask, 0, len(*req.Tasks))
	ids := make(map[string]struct{}, len(*req.Tasks))
	priorities := make(map[int64]struct{}, len(*req.Tasks))
	for i := range *req.Tasks {
		in := &(*req.Tasks)[i]
		if !validTaskID(in.ID) {
			return nil, false
		}
		if _, dup := ids[in.ID]; dup {
			return nil, false
		}
		ids[in.ID] = struct{}{}
		if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
			return nil, false
		}
		if _, dup := priorities[*in.Priority]; dup {
			return nil, false
		}
		priorities[*in.Priority] = struct{}{}
		if in.Execution == nil || *in.Execution <= 0 || *in.Execution > maxPeriodicField {
			return nil, false
		}
		if in.Period == nil || *in.Period <= 0 || *in.Period > maxPeriodicField {
			return nil, false
		}
		if in.Deadline == nil || *in.Deadline <= 0 ||
			*in.Deadline > maxPeriodicField || *in.Deadline > *in.Period {
			return nil, false
		}
		tasks = append(tasks, periodicTask{
			index:     i,
			id:        in.ID,
			priority:  *in.Priority,
			execution: *in.Execution,
			period:    *in.Period,
			deadline:  *in.Deadline,
		})
	}
	return tasks, true
}

// analyzePeriodic applies rate-monotonic-style fixed-point response-time
// analysis under synchronous release, full preemption, no blocking and no
// release jitter. Tasks are processed from highest to lowest priority; the
// response of task k is the least fixed point of
//
//	w = C_k + Σ_{j∈hp(k)} ceil(w/T_j) C_j,
//
// provided it does not exceed D_k. Input order is preserved in the results.
func analyzePeriodic(tasks []periodicTask) periodicAnalyzeResponse {
	n := len(tasks)
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		return tasks[order[a]].priority < tasks[order[b]].priority
	})
	byPriority := make([]periodicTask, n)
	for i, idx := range order {
		byPriority[i] = tasks[idx]
	}

	results := make([]periodicTaskResult, n)
	schedulable := true
	hpUtilization := new(big.Rat)
	one := big.NewRat(1, 1)
	for rank := range byPriority {
		t := byPriority[rank]
		var response *int64
		// Σ C_j/T_j ≥ 1 makes f(w) = C_k + Σ C_j ceil(w/T_j) strictly
		// greater than w for every w, so no fixed point exists. The exact
		// rational test also keeps iteration pseudo-polynomial worst cases
		// (e.g. a T=C=1 interferer) terminating immediately.
		if hpUtilization.Cmp(one) < 0 {
			response = worstResponseTime(t, byPriority[:rank])
		}
		status := "met"
		if response == nil {
