func periodicResultEqual(a, b periodicTaskResult) bool {
	if a.ID != b.ID || a.DeadlineStatus != b.DeadlineStatus {
		return false
	}
	if (a.ResponseTime == nil) != (b.ResponseTime == nil) {
		return false
	}
	return a.ResponseTime == nil || *a.ResponseTime == *b.ResponseTime
}

