119	// analyzePeriodic applies fixed-priority worst-case response-time analysis
120	// under synchronous release, full preemption, no blocking and no release
121	// jitter. Tasks are processed from highest to lowest priority; the response
122	// of task k is the least fixed point of
123	//
124	//	w = C_k + Σ_{j∈hp(k)} ceil(w/T_j) C_j,
125	//
126	// provided it does not exceed D_k. Results keep the input order.
127	func analyzePeriodic(tasks []periodicTask) periodicAnalyzeResponse {
128		n := len(tasks)
129		byPriority := make([]periodicTask, n)
130		copy(byPriority, tasks)
131		sort.SliceStable(byPriority, func(a, b int) bool {
132			return byPriority[a].priority < byPriority[b].priority
133		})
134	
135		results := make([]periodicTaskResult, n)
136		schedulable := true
137		// Exact cumulative higher-priority utilization Σ C_j/T_j. At Σ ≥ 1 the
138		// iteration f(w) = C_k + Σ C_j ceil(w/T_j) satisfies f(w) > w for every
139		// w, so no fixed point exists; the early exit also bounds work on
140		// pseudo-polynomial worst cases such as a T_j = C_j interferer.
141		hpUtilization := new(big.Rat)
142		one := big.NewRat(1, 1)
143		for rank := range byPriority {
144			t := byPriority[rank]
145			var response *int64
146			if hpUtilization.Cmp(one) < 0 {
147				response = worstResponseTime(t, byPriority[:rank])
148			}
149			status := "met"
150			if response == nil {
151				status = "missed"
152				schedulable = false
153			}
154			results[t.index] = periodicTaskResult{
155				ID:             t.id,
156				ResponseTime:   response,
157				DeadlineStatus: status,
158			}
159			hpUtilization.Add(hpUtilization,
160				new(big.Rat).SetFrac(big.NewInt(t.execution), big.NewInt(t.period)))
161		}
162		return periodicAnalyzeResponse{Schedulable: schedulable, Results: results}
163	}
164	
165	// worstResponseTime iterates the fixed-point equation starting from w0 = C_k
166	// and returns the converged value when it never exceeds the deadline. The
167	// initial value or any iteration result above the deadline, or an int64
168	// overflow, yields nil. f is non-decreasing and the sequence starts at a
169	// lower bound, so every accepted value strictly increases until it fixes.
170	func worstResponseTime(t periodicTask, higher []periodicTask) *int64 {
171		w := t.execution
172		if w > t.deadline {
173			return nil
174		}
175		for {
176			next, overflow := rtaIteration(w, t.execution, higher)
177			if overflow || next > t.deadline {
178				return nil
179			}
180			if next == w {
181				value := w
182				return &value
183			}
184			w = next
185		}
186	}
187	
188	// rtaIteration computes C_k + Σ ceil(w/T_j) C_j with checked 64-bit
189	// arithmetic. Individual products can reach ~1e24, so multiplication and
190	// accumulation are widened to 128 bits; a total outside int64 is reported as
191	// overflow instead of wrapping.
192	func rtaIteration(w, execution int64, higher []periodicTask) (int64, bool) {
193		sum := uint64(execution)
194		var hi uint64
195		for _, j := range higher {
196			// w and T_j are positive and at most 1e12, so w + T_j - 1 cannot wrap.
197			q := uint64((w + j.period - 1) / j.period)
198			prodHi, prodLo := bits.Mul64(q, uint64(j.execution))
199			var carry uint64
200			sum, carry = bits.Add64(sum, prodLo, 0)
201			hi, _ = bits.Add64(hi, prodHi, carry)
202		}
203		if hi != 0 || sum > maxInt64Uint {
204			return 0, true
205		}
206		return int64(sum), false
207	}
